const modalStack=[];
function syncModalStack(){
  for(let index=modalStack.length-1;index>=0;index--)if(!document.querySelector(`#${modalStack[index]}`)?.classList.contains('open'))modalStack.splice(index,1);
  modalStack.forEach((name,index)=>{
    const backdrop=document.querySelector(`#${name}`),top=index===modalStack.length-1;
    if(!backdrop)return;
    backdrop.style.zIndex=String(20+index*2);
    backdrop.classList.toggle('modal-underlay',!top);
    backdrop.classList.toggle('modal-top',top);
    top?backdrop.removeAttribute('aria-hidden'):backdrop.setAttribute('aria-hidden','true');
  });
  document.body.classList.toggle('modal-open',modalStack.length>0);
}
function openModal(name){
  const backdrop=document.querySelector(`#${name}`);
  if(!backdrop)return;
  if(!backdrop.classList.contains('open')){
    backdrop.classList.add('open');
    modalStack.push(name);
  }else if(!modalStack.includes(name))modalStack.push(name);
  syncModalStack();
}
function closeModal(name){
  const backdrop=document.querySelector(`#${name}`);
  if(!backdrop)return;
  backdrop.classList.remove('open','modal-underlay','modal-top');
  backdrop.style.removeProperty('z-index');
  backdrop.removeAttribute('aria-hidden');
  const stackIndex=modalStack.lastIndexOf(name);
  if(stackIndex>=0)modalStack.splice(stackIndex,1);
  syncModalStack();
}
function closeTopModal(){const name=modalStack[modalStack.length-1];if(name)closeModal(name)}
