  document.querySelector('#moneyReceivedTotal').textContent=euro(received);document.querySelector('#moneyOutstandingTotal').textContent=euro(outstanding);document.querySelector('#installmentDueTotal').textContent=euro(planned);document.querySelector('#expenseTotal').textContent=euro(total);document.querySelector('#expensePaid').textContent=euro(paid);document.querySelector('#expenseDue').textContent=euro(total-paid);
  document.querySelector('#installmentTableBody').innerHTML=state.installments.filter(item=>{const client=clientBy(item.clientId);return matchesSearch([client?.name,client?.email,cruiseName(client?.cruiseId),item.notes,item.amount,item.currency,item.dueDate,item.status],searchFilters.installments)}).slice().sort((a,b)=>String(a.dueDate||'').localeCompare(String(b.dueDate||''))).map(item=>{const client=clientBy(item.clientId),payment=state.payments.find(record=>Number(record.id)===Number(item.paymentId)),late=!payment&&item.dueDate<TODAY,converted=item.currency!=='EUR'?`<div class="subtext">${euro(paymentEurValue(item))} ${translatedText('for balance')}</div>`:'';return `<tr>${dataCell('Deadline',formatDate(item.dueDate),late?'overdue':'')}${dataCell('Client',`<strong>${esc(client?.name||'Deleted client')}</strong><div class="subtext">${esc(cruiseName(client?.cruiseId))}</div>`)}${dataCell('Remarks',esc(item.notes||'—'))}${dataCell('Expected amount',`<strong>${money(item.amount,item.currency)}</strong>${converted}`,'number')}${dataCell('Status',`<span class="status ${payment?'paid':late?'unpaid':'waiting'}">${payment?'Received':late?'Overdue':'Scheduled'}</span>`)}${dataCell('Actions',`<div class="actions-cell"><button type="button" class="icon-action" data-edit-installment="${item.id}">Edit</button>${payment?`<button type="button" class="icon-action" data-edit-payment="${payment.id}">View payment</button>`:`<button type="button" class="icon-action" data-pay-installment="${item.id}">Record client payment</button>`}<button type="button" class="icon-action danger" data-delete-installment="${item.id}">Delete</button></div>`)}</tr>`}).join('')||`<tr>${dataCell('Future client payments',empty('No scheduled payments. Add one for a booked client.'))}</tr>`;
  const expenseRows=state.expenses.filter(expense=>(searchFilters.expenseCategory==='all'||expense.category===searchFilters.expenseCategory)&&(searchFilters.expenseStatus==='all'||expense.status===searchFilters.expenseStatus)&&matchesSearch([expense.category,expense.payee,expense.reference,expense.notes,cruiseName(expense.cruiseId),expense.amount],searchFilters.expenses)).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
  document.querySelector('#expenseTableBody').innerHTML=expenseRows.map(expense=>{const late=expense.status!=='Paid'&&expense.dueDate&&expense.dueDate<TODAY,managed=expense.managedBy==='commission',timing=expense.status==='Paid'?`<strong>${translatedText('Paid on')}</strong><div class="subtext">${formatDate(expense.paidDate||expense.date)}</div>`:managed?`${formatDate(expense.dueDate)}${late?'<div class="subtext overdue">Overdue</div>':''}`:`<input class="table-input date-input ${late?'deadline-late':''}" type="date" value="${expense.dueDate||''}" data-expense-deadline="${expense.id}" aria-label="Payment deadline for ${esc(expense.payee)}">${late?'<div class="subtext overdue">Overdue</div>':''}`;return `<tr>${dataCell('Invoice / expense date',formatDate(expense.date))}${dataCell('Cruise',esc(cruiseName(expense.cruiseId)))}${dataCell('Category / payee',`<strong>${esc(expense.category)}</strong><div class="subtext">${esc(expense.payee)}${expense.reference?` · ${esc(expense.reference)}`:''}</div>${managed?'<span class="managed-note">Managed in Partners</span>':''}`)}${dataCell('Payment timing',timing)}${dataCell('Expense remarks',esc(expense.notes||'—'))}${dataCell('Status',managed?`<span class="status ${expense.status==='Paid'?'paid':'unpaid'}">${esc(expense.status)}</span>`:`<button class="status ${expense.status==='Paid'?'paid':'unpaid'}" data-toggle-expense="${expense.id}" title="Change payment status">${esc(expense.status)}</button>`)}${dataCell('Amount',`<strong>${euro(expense.amount)}</strong>`,'number')}${dataCell('Actions',managed?'<button class="icon-action" data-view="partners">Open Partners</button>':`<div class="actions-cell"><button class="icon-action" data-edit-expense="${expense.id}">Edit</button><button class="icon-action danger" data-delete-expense="${expense.id}">Delete</button></div>`)}</tr>`}).join('')||`<tr>${dataCell('Expenses',empty('No expenses match these filters.'))}</tr>`;
  document.querySelectorAll('#expenseTableBody [data-edit-expense],#expenseTableBody [data-delete-expense],#expenseTableBody [data-toggle-expense]').forEach(button=>button.type='button');
