function renderPeople(){for(const type of ['Crew','Supplier']){const target=document.querySelector(type==='Crew'?'#crewList':'#supplierList'),rows=state.people.filter(person=>person.type===type&&matchesSearch([person.name,person.role,person.phone,person.email,person.rate],searchFilters.people));target.innerHTML=rows.map(p=>`<div class="contact"><span class="avatar">${initials(p.name)}</span><div><div class="person-name">${esc(p.name)}</div><div class="subtext">${esc(p.role)} · ${esc(p.phone||p.email||'No contact details')}</div></div><div><div class="contact-rate">${esc(p.rate||'Rate not entered')}</div><div class="contact-actions"><button class="icon-action" data-edit-person="${p.id}">Edit</button><button class="icon-action danger" data-delete-person="${p.id}">Delete</button></div></div></div>`).join('')||empty(`No matching ${type.toLowerCase()} contacts.`)}}
function renderMarketing(){
  const year=fillPeriodSelect('#marketingYear'),periodClients=state.clients.filter(client=>client.stage!=='Cancelled'&&clientMatchesYear(client,year)),periodBooked=periodClients.filter(client=>client.stage==='Booked'),spend=state.expenses.filter(expense=>expense.category==='Marketing'&&(year==='all'||yearOf(expense.date)===year)).reduce((sum,expense)=>sum+Number(expense.amount||0),0),leads=periodClients.length,booked=periodBooked.length,revenue=periodBooked.reduce((sum,client)=>sum+Number(client.bookingValue||0),0),conversion=leads?booked/leads*100:0;
  document.querySelector('#marketingKpis').innerHTML=[['Marketing spend',euro(spend),'Recorded marketing expenses'],['Enquiries',leads,'Active clients in this period'],['Conversion',`${conversion.toFixed(0)}%`,'Clients that became bookings'],['Booked revenue',euro(revenue),'Revenue influenced by sources']].map(item=>`<article class="card kpi"><span>${item[0]}</span><strong>${item[1]}</strong><small>${item[2]}</small></article>`).join('');
  const grouped={};periodClients.forEach(client=>{const item=grouped[client.source]||(grouped[client.source]={leads:0,booked:0,revenue:0});item.leads++;if(client.stage==='Booked'){item.booked++;item.revenue+=Number(client.bookingValue||0)}});
  const max=Math.max(1,...Object.values(grouped).map(item=>item.revenue));
  document.querySelector('#sourcePerformance').innerHTML=Object.entries(grouped).sort((a,b)=>b[1].revenue-a[1].revenue).map(([name,item])=>`<div class="source-item"><div class="source-top"><strong>${esc(name)}</strong><strong>${euro(item.revenue)}</strong></div><div class="source-meta"><span>${item.leads} ${item.leads===1?'enquiry':'enquiries'}</span><span>${item.booked} ${item.booked===1?'booking':'bookings'}</span><span>${item.leads?Math.round(item.booked/item.leads*100):0}% conversion</span></div><div class="source-bar"><span style="width:${item.revenue/max*100}%"></span></div></div>`).join('')||empty('Add client sources to see performance.');
  document.querySelector('#marketingTasks').innerHTML=state.marketingTasks.filter(task=>year==='all'||yearOf(task.date)===year).sort((a,b)=>a.date.localeCompare(b.date)).map(task=>`<div class="task ${task.done?'done':''}"><input type="checkbox" data-toggle-task="${task.id}" ${task.done?'checked':''} aria-label="Complete ${esc(task.title)}"><div><div class="task-title">${esc(task.title)}</div><div class="task-meta">${formatDate(task.date)} · ${esc(task.channel)}</div></div><button class="icon-action danger" data-delete-task="${task.id}" aria-label="Delete content task">Delete</button></div>`).join('')||empty('No content tasks for this period.');
  const top=Object.entries(grouped).sort((a,b)=>b[1].booked-a[1].booked)[0];document.querySelector('#marketingAdvice').innerHTML=[top?`${esc(top[0])} currently produces the most bookings. Reuse the message and imagery that attracted those clients.`:'Start recording a marketing source for every enquiry.',`Marketing cost per active enquiry is ${euro(leads?spend/leads:0)}. Compare this monthly before increasing ad spend.`,'Use “7-day SUP cruise in Greece” naturally in page titles, Google Business posts and photo descriptions.','Publish real guest reactions and availability with one clear action: check dates, message Hadar, or reserve a place.'].map(item=>`<div class="advice-item">${item}</div>`).join('');
}
function renderPartners(){
  const referred=state.clients.filter(client=>partnerBy(client.partnerId)),booked=referred.filter(client=>client.stage==='Booked'),bookedRevenue=booked.reduce((sum,client)=>sum+Number(client.bookingValue||0),0),bookedCommissions=state.commissions.filter(commission=>clientBy(commission.clientId)?.stage==='Booked'),outstanding=bookedCommissions.filter(commission=>commission.status!=='Paid').reduce((sum,commission)=>sum+Number(commission.amount||0),0),paid=state.commissions.filter(commission=>commission.status==='Paid').reduce((sum,commission)=>sum+Number(commission.amount||0),0);
  document.querySelector('#partnerKpis').innerHTML=kpiCards([['Partners',state.partners.length,'Saved collaborators'],['Referred clients',referred.length,'Leads and bookings'],['Booked revenue',euro(bookedRevenue),'Revenue from partners'],['Commission committed',euro(outstanding),`${euro(paid)} already paid`]]);
  document.querySelector('#partnerTableBody').innerHTML=state.partners.filter(partner=>matchesSearch([partner.name,partner.contact,partner.email,partner.phone,partner.notes,...referred.filter(client=>Number(client.partnerId)===Number(partner.id)).map(client=>client.name)],searchFilters.partners)).sort((a,b)=>a.name.localeCompare(b.name)).map(partner=>{const clients=referred.filter(client=>Number(client.partnerId)===Number(partner.id)),partnerBooked=clients.filter(client=>client.stage==='Booked'),commissions=state.commissions.filter(commission=>Number(commission.partnerId)===Number(partner.id)),owed=commissions.filter(commission=>clientBy(commission.clientId)?.stage==='Booked'&&commission.status!=='Paid').reduce((sum,commission)=>sum+Number(commission.amount||0),0),paidAmount=commissions.filter(commission=>commission.status==='Paid').reduce((sum,commission)=>sum+Number(commission.amount||0),0);return `<tr>${dataCell('Partner',`<div class="client-cell"><span class="avatar">${initials(partner.name)}</span><div><strong>${esc(partner.name)}</strong><div class="subtext">${esc(partner.contact||partner.email||partner.phone||'No contact details')}</div></div></div>`)}${dataCell('Agreement',partner.commissionType==='Percentage'?`${Number(partner.commissionValue||0).toLocaleString()}% of booking`:`${euro(partner.commissionValue)} per booking`)}${dataCell('Referred clients',clients.length,'number')}${dataCell('Booked revenue',euro(partnerBooked.reduce((sum,client)=>sum+Number(client.bookingValue||0),0)),'number')}${dataCell('Commission owed',euro(owed),'number')}${dataCell('Commission paid',euro(paidAmount),'number')}${dataCell('Actions',`<div class="actions-cell"><button class="icon-action" data-edit-partner="${partner.id}">Edit</button><button class="icon-action danger" data-delete-partner="${partner.id}">Delete</button></div>`)}</tr>`}).join('')||`<tr>${dataCell('Partners',empty('No partners match this search.'))}</tr>`;
  document.querySelector('#commissionTableBody').innerHTML=state.commissions.filter(commission=>{const client=clientBy(commission.clientId),partner=partnerBy(commission.partnerId);return matchesSearch([client?.name,client?.email,partner?.name,commission.notes,commission.reference],searchFilters.partners)}).sort((a,b)=>String(b.createdDate||'').localeCompare(String(a.createdDate||''))).map(commission=>{
    const client=clientBy(commission.clientId),partner=partnerBy(commission.partnerId);if(!client||!partner)return'';
    const status=commissionState(commission),statusClass=status==='Paid'?'paid':status==='Ready to pay'?'booked':status==='Cancelled'?'cancelled':status==='Not booked'?'missing':'waiting',payAction=status==='Ready to pay'?`<button class="icon-action" data-pay-commission="${commission.id}">Pay partner</button>`:'',manageLabel=status==='Paid'?'View payment':'Manage';
    return `<tr>${dataCell('Client',`<strong>${esc(client.name)}</strong><div class="subtext">${esc(cruiseName(client.cruiseId))}</div>`)}${dataCell('Partner',esc(partner.name))}${dataCell('Client payment',`${euro(paidFor(client.id))} / ${euro(client.bookingValue)}`)}${dataCell('Agreement',commissionAgreement(commission))}${dataCell('Commission',`<strong>${euro(commission.amount)}</strong>`,'number')}${dataCell('Partner deadline',`<input class="table-input date-input ${commission.status!=='Paid'&&commission.dueDate&&commission.dueDate<TODAY?'deadline-late':''}" type="date" value="${commission.dueDate||''}" data-commission-deadline="${commission.id}" aria-label="Partner payment deadline for ${esc(client.name)}">`)}${dataCell('Status',`<span class="status ${statusClass}">${esc(status)}</span>`)}${dataCell('Actions',`<div class="actions-cell">${payAction}<button class="icon-action" data-edit-commission="${commission.id}">${manageLabel}</button></div>`)}</tr>`;
  }).join('')||`<tr>${dataCell('Commissions',empty('No commissions match this search.'))}</tr>`;
}

function clientYear(c){const cruise=cruiseBy(c.cruiseId);return cruise?.startDate.slice(0,4)||c.followup?.slice(0,4)||'Unknown'}
function renderReportFilters(){const year=document.querySelector('#reportYear'),source=document.querySelector('#reportSource'),y=year.value||'all',s=source.value||'all',years=[...new Set([...state.cruises.map(c=>c.startDate.slice(0,4)),...state.clients.map(clientYear)].filter(Boolean))].sort().reverse(),sources=[...new Set(state.clients.map(c=>c.source).filter(Boolean))].sort();year.innerHTML='<option value="all">All years</option>'+years.map(v=>`<option>${esc(v)}</option>`).join('');source.innerHTML='<option value="all">All sources</option>'+sources.map(v=>`<option>${esc(v)}</option>`).join('');year.value=years.includes(y)?y:'all';source.value=sources.includes(s)?s:'all'}
