  summary.textContent=`${translatedText('Total booking price')}: ${euro(client.bookingValue)} · ${translatedText('Received so far')}: ${euro(paidFor(client.id))} · ${translatedText('Remaining balance')}: ${euro(balanceFor(client))}`;
