function preparePerson(personId){const form=document.querySelector('#personForm');resetForm(form);form.elements.type.value='Crew';form.elements.crewRole.value='Skipper';const p=state.people.find(x=>Number(x.id)===Number(personId));if(p){setForm(form,p);if(p.type==='Crew'){const knownRoles=['Skipper','SUP guide','Cook'],role=String(p.role||'').trim();form.elements.crewRole.value=knownRoles.includes(role)?role:role?'Other':'Skipper';form.elements.crewOtherRole.value=knownRoles.includes(role)?'':role}else form.elements.supplierService.value=p.role||''}document.querySelector('#personCruiseChecklist').innerHTML=state.cruises.slice().sort((a,b)=>a.startDate.localeCompare(b.startDate)).map(cruise=>`<label><input type="checkbox" value="${cruise.id}" ${(p?.cruiseIds||[]).some(id=>Number(id)===Number(cruise.id))?'checked':''}> <span>${esc(cruise.name)} · ${formatDate(cruise.startDate)}</span></label>`).join('')||'<span class="subtext">Add a cruise before assigning crew.</span>';toggleCrewDetails();openModal('personModal')}
function toggleCrewDetails(){const crew=document.querySelector('#personType').value==='Crew';document.querySelector('#crewDetailsFields').hidden=!crew;updatePersonRoleFields();updatePersonModalCopy();applyLanguage()}
function prepareExhibition(exhibitionId){const form=document.querySelector('#exhibitionForm');resetForm(form);form.elements.startDate.value=addDays(TODAY,30);form.elements.endDate.value=addDays(TODAY,31);const exhibition=state.exhibitions.find(item=>Number(item.id)===Number(exhibitionId));if(exhibition)setForm(form,exhibition);syncEndDateMinimum(form);document.querySelector('#exhibitionModalTitle').textContent=exhibition?'Edit exhibition':'Add exhibition';openModal('exhibitionModal')}
function prepareExhibitionTask(exhibitionId){const exhibition=state.exhibitions.find(item=>Number(item.id)===Number(exhibitionId)),form=document.querySelector('#exhibitionTaskForm');form.reset();form.elements.exhibitionId.value=exhibitionId;form.elements.dueDate.value=exhibition?.startDate||addDays(TODAY,7);document.querySelector('#exhibitionTaskHelp').textContent=`Preparation task for ${exhibition?.name||'this exhibition'}.`;openModal('exhibitionTaskModal')}
function preparePartner(partnerId){const form=document.querySelector('#partnerForm');resetForm(form);form.elements.commissionValue.value=10;const partner=partnerBy(partnerId);if(partner)setForm(form,partner);document.querySelector('#partnerModalTitle').textContent=partner?'Edit partner':'Add partner';openModal('partnerModal')}
function updateCommissionPaymentFields(){const form=document.querySelector('#commissionForm'),paid=form.elements.status.value==='Paid';form.elements.paidDate.required=paid;if(paid&&!form.elements.paidDate.value)form.elements.paidDate.value=TODAY}
function prepareCommission(commissionId,paymentMode=false){const commission=state.commissions.find(item=>Number(item.id)===Number(commissionId)),client=clientBy(commission?.clientId),partner=partnerBy(commission?.partnerId);if(!commission||!client||!partner)return;if(paymentMode&&commissionState(commission)!=='Ready to pay'){showToast('The client must pay in full before the partner commission is marked paid');return}const form=document.querySelector('#commissionForm');resetForm(form);setForm(form,commission);if(paymentMode){form.elements.status.value='Paid';form.elements.paidDate.value=TODAY}const paymentRecord=paymentMode||commission.status==='Paid';document.querySelector('#commissionModalTitle').textContent=paymentRecord?'Pay partner':'Manage commission';document.querySelector('#commissionSaveButton').textContent=paymentRecord?'Save partner payment':'Save commission';document.querySelector('#commissionModalHelp').textContent=`${partner.name} · referred ${client.name} · calculated commission ${euro(commission.amount)}`;updateCommissionPaymentFields();openModal('commissionModal');applyLanguage()}

function openReceiptDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('supcruise-files',1);req.onupgradeneeded=()=>req.result.createObjectStore('receipts');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function saveReceipt(paymentId,file){const db=await openReceiptDB();await new Promise((resolve,reject)=>{const tx=db.transaction('receipts','readwrite');tx.objectStore('receipts').put(file,String(paymentId));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
async function getReceipt(paymentId){const db=await openReceiptDB(),file=await new Promise((resolve,reject)=>{const req=db.transaction('receipts').objectStore('receipts').get(String(paymentId));req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});db.close();return file}
async function deleteReceipt(paymentId){const db=await openReceiptDB();await new Promise((resolve,reject)=>{const tx=db.transaction('receipts','readwrite');tx.objectStore('receipts').delete(String(paymentId));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
async function clearReceipts(){const db=await openReceiptDB();await new Promise((resolve,reject)=>{const tx=db.transaction('receipts','readwrite');tx.objectStore('receipts').clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function csvEscape(v){const s=String(v??'');return /[",\n]/.test(s)?`"${s.replaceAll('"','""')}"`:s}
function exportReport(){if(!currentReportRows.length){showToast('No report rows to export');return}const csv=[currentReportRows.headers,...currentReportRows].map(r=>r.map(csvEscape).join(',')).join('\n');downloadBlob(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),`supcruise-${document.querySelector('#reportType').value}-${TODAY}.csv`)}
function backup(){downloadBlob(new Blob([JSON.stringify({version:4,exportedAt:new Date().toISOString(),data:state},null,2)],{type:'application/json'}),`supcruise-backup-${TODAY}.json`);showToast('Backup downloaded')}
function normalizeRestoredState(){for(const key of Object.keys(seed))if(!Array.isArray(state[key]))state[key]=[];state.people.forEach(person=>{if(!Array.isArray(person.cruiseIds))person.cruiseIds=[];person.dob=person.dob||'';person.passport=person.passport||'';person.gender=person.gender||''});state.exhibitions.forEach(exhibition=>{if(!Array.isArray(exhibition.tasks))exhibition.tasks=[]});state.guests.forEach(guest=>normalizePassengerRecord(guest));state.clients.forEach(client=>normalizeClientRecord(client,state.guests));state.clients.filter(client=>client.stage==='Booked').forEach(client=>ensurePrimaryPassenger(client));state.expenses.forEach(expense=>{expense.paidDate=expense.paidDate||(expense.status==='Paid'?expense.dueDate||expense.date||'':'');if(expense.status==='Paid')expense.dueDate=''});state.payments.forEach(payment=>{payment.status=['Received','Cancelled'].includes(payment.status)?payment.status:'Received';payment.currency=['EUR','ILS','USD'].includes(payment.currency)?payment.currency:'EUR';payment.eurAmount=payment.currency==='EUR'?Number(payment.amount||0):Number(payment.eurAmount||0)});state.installments.forEach(item=>{item.currency=['EUR','ILS','USD'].includes(item.currency)?item.currency:'EUR';item.eurAmount=item.currency==='EUR'?Number(item.amount||0):Number(item.eurAmount||0)})}
async function restore(file){const parsed=JSON.parse(await file.text());if(!parsed?.data||!Array.isArray(parsed.data.clients)||!Array.isArray(parsed.data.cruises))throw new Error('This is not a valid SUPCruise backup');if(!askConfirm('Replace the records on this device with this backup?'))return;await clearReceipts();state=parsed.data;normalizeRestoredState();workspaceMode='live';localStorage.setItem(WORKSPACE_MODE_KEY,workspaceMode);render();showToast('Workspace restored from backup')}
async function startEmptyWorkspace(){if(!askConfirm('Start an empty workspace? This removes all current records on this device. Download a backup first if you need to keep them.'))return;await clearReceipts();state=emptyState();workspaceMode='live';localStorage.setItem(WORKSPACE_MODE_KEY,workspaceMode);render();showToast('Empty workspace ready')}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i],next=text[i+1];if(ch==='"'&&quoted&&next==='"'){cell+='"';i++}else if(ch==='"')quoted=!quoted;else if(ch===','&&!quoted){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&next==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=ch}row.push(cell);if(row.some(Boolean))rows.push(row);return rows}
const normalized=s=>String(s||'').toUpperCase().replace(/[^A-Z0-9]+/g,' '),responseValue=(record,words)=>{const key=Object.keys(record).find(k=>words.every(w=>normalized(k).includes(w)));return key?record[key].trim():''};
async function importGuestCSV(file){const rows=parseCSV(await file.text());if(rows.length<2)throw new Error('The CSV has no response rows');const headers=rows[0];let imported=0,unmatched=0;for(const values of rows.slice(1)){const record={};headers.forEach((h,i)=>record[h]=values[i]||'');const name=responseValue(record,['FULL','NAME'])||responseValue(record,['NAME']),email=responseValue(record,['EMAIL']);if(!name&&!email)continue;const client=state.clients.find(c=>(email&&c.email.toLowerCase()===email.toLowerCase())||c.name.toLowerCase()===name.toLowerCase()),existing=state.guests.find(g=>(email&&g.email.toLowerCase()===email.toLowerCase())||g.name.toLowerCase()===name.toLowerCase()),guest={id:existing?.id||id(),clientId:client?.id||existing?.clientId||null,name:name||existing?.name||'Unnamed traveller',email:email||existing?.email||'',relationship:existing?.relationship||'Traveller',status:'Received',deadline:existing?.deadline||addDays(TODAY,7),sup:responseValue(record,['SUP','EXPERIENCE']),swimming:responseValue(record,['SWIM']),dietary:responseValue(record,['DIETARY']),health:responseValue(record,['PHYSICAL']),terms:Boolean(responseValue(record,['AGREE']))};existing?Object.assign(existing,guest):state.guests.push(guest);if(!client)unmatched++;imported++}render();return{imported,unmatched}}

function switchView(view){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`${view}View`));document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const titles={dashboard:'Business overview',clients:'Clients',operations:'Cruises & clients',finance:'Money received & paid',people:'Crew & suppliers',marketing:'Marketing performance',partners:'Partners & commissions',reports:'Reports & backup'};document.querySelector('#pageTitle').textContent=titles[view];document.querySelector('#quickExpense').hidden=view!=='dashboard';document.querySelector('#quickClient').hidden=!['dashboard','clients'].includes(view);document.querySelector('#sidebar').classList.remove('open');document.querySelector('#menuScrim').classList.remove('open');if(view==='reports')renderReports();applyLanguage();window.scrollTo({top:0,behavior:'smooth'})}
