  const receipt=e.target.closest('[data-download-receipt]');if(receipt){const p=state.payments.find(x=>x.id===Number(receipt.dataset.downloadReceipt)),file=await getReceipt(p.id);file?downloadBlob(file,p.receiptName):showToast('The original receipt file is not stored on this device')}
  const editCruise=e.target.closest('[data-edit-cruise]');if(editCruise)prepareCruise(Number(editCruise.dataset.editCruise));
  const cancelCruise=e.target.closest('[data-cancel-cruise]');if(cancelCruise){const cruiseId=Number(cancelCruise.dataset.cancelCruise),cruise=cruiseBy(cruiseId);if(cruise&&cruiseIsCancelled(cruise))return;if(cruise&&cruiseHasPaidRecords(cruiseId)){showToast('This cruise cannot be cancelled because paid payments are attached.');return}if(cruise&&askConfirm('Cancel this cruise? Linked clients and crew will remain attached.')){cruise.status='Cancelled';if(document.querySelector('#cruiseDetailModal')?.classList.contains('open'))closeModal('cruiseDetailModal');render();showToast('Cruise cancelled')}}
  const removeCruise=e.target.closest('[data-remove-cruise]');if(removeCruise){const cruiseId=Number(removeCruise.dataset.removeCruise),cruise=cruiseBy(cruiseId);if(!cruise||!cruiseIsCancelled(cruise))return;const linked=cruiseLinkedRecords(cruiseId);if(linked.length){showToast(`${translatedText('This cruise still has attached records:')} ${linked.map(([name,n])=>`${n} ${translatedText(name)}`).join(', ')}`);return}if(askConfirm('Remove this cancelled cruise permanently? This cannot be undone.')){state.cruises=state.cruises.filter(item=>Number(item.id)!==cruiseId);if(document.querySelector('#cruiseDetailModal')?.classList.contains('open'))closeModal('cruiseDetailModal');saveState();render();showToast('Cruise removed')}}
