  const payCommission=e.target.closest('[data-pay-commission]');if(payCommission)prepareCommission(Number(payCommission.dataset.payCommission),true);
  const editCommission=e.target.closest('[data-edit-commission]');if(editCommission)prepareCommission(Number(editCommission.dataset.editCommission));
  const deleteTask=e.target.closest('[data-delete-task]');if(deleteTask&&askConfirm('Delete this content task?')){state.marketingTasks=state.marketingTasks.filter(x=>x.id!==Number(deleteTask.dataset.deleteTask));render()}
