document.querySelector('#clientForm').addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),existing=clientBy(Number(d.id)),email=normalizedEmail(d.email),phone=normalizedPhone(d.phone),duplicateEmail=email&&state.clients.some(client=>client.id!==existing?.id&&normalizedEmail(client.email)===email),duplicatePhone=phone&&state.clients.some(client=>client.id!==existing?.id&&normalizedPhone(client.phone)===phone);if(duplicateEmail){showToast('A client with this email already exists.');return}if(duplicatePhone){showToast('A client with this phone number already exists.');return}d.bookingValue=Number(d.bookingValue||0);d.partySize=Math.max(1,Number(d.partySize)||1);d.roomType=['Not decided','Single room','Small double room','Large double room'].includes(d.roomType)?d.roomType:'Not decided';if(d.stage==='Booked'&&d.bookingValue<=0){showToast('Enter a confirmed booking value for a booked client.');return}const partnerId=d.source==='Referral'&&d.partnerId?Number(d.partnerId):null,paidCommission=existing&&state.commissions.find(commission=>Number(commission.clientId)===Number(existing.id)&&commission.status==='Paid');if(paidCommission&&Number(existing.partnerId||0)!==Number(partnerId||0)){showToast('A paid commission exists. Keep this partner or correct the commission first.');return}d.id=existing?.id||id();d.cruiseId=d.cruiseId?Number(d.cruiseId):null;d.partnerId=partnerId;if(d.stage!=='Booked')d.paymentDue='';if(d.partnerId)d.source='Referral';existing?Object.assign(existing,d):state.clients.unshift(d);ensurePrimaryPassenger(existing||d);closeModal('clientModal');render();showToast(`${d.name} saved`)});
document.querySelector('#paymentForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.target,d=Object.fromEntries(new FormData(form)),existing=state.payments.find(p=>p.id===Number(d.id)),client=clientBy(Number(d.clientId)),amount=Number(d.amount);if(!client||Number(client.bookingValue)<=0){showToast('Open the client card and enter the total booking price first.');return}if(!existing&&client.stage!=='Booked'){showToast('Mark the client as Booked before recording a payment.');return}d.status=existing?.status==='Cancelled'?'Cancelled':'Received';d.currency=['EUR','ILS','USD'].includes(d.currency)?d.currency:'EUR';d.eurAmount=d.currency==='EUR'?amount:Number(d.eurAmount||0);const available=balanceFor(client)+(existing?.status==='Cancelled'?0:paymentEurValue(existing));if(d.eurAmount<=0){showToast('Enter the EUR equivalent used for the client balance.');return}if(d.eurAmount>available){showToast(`Amount exceeds the available balance of ${euro(available)}`);return}const file=form.elements.receipt.files[0];d.id=existing?.id||id();d.clientId=Number(d.clientId);d.installmentId=d.installmentId?Number(d.installmentId):null;d.amount=amount;d.receiptName=file?.name||existing?.receiptName||'';existing?Object.assign(existing,d):state.payments.unshift(d);if(d.installmentId){const installment=installmentBy(d.installmentId);if(installment)installment.paymentId=d.id}if(file)await saveReceipt(d.id,file);closeModal('paymentModal');render();showToast(`${money(amount,d.currency)} payment saved for ${client.name}`)});
document.querySelector('#cruiseForm').addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),existing=cruiseBy(Number(d.id));if(d.endDate<d.startDate){showToast('The cruise end date cannot be earlier than the start date.');return}d.id=existing?.id||id();d.capacity=Number(d.capacity);existing?Object.assign(existing,d):state.cruises.push(d);closeModal('cruiseModal');render();showToast(`${d.name} cruise saved`)});
document.querySelector('#expenseForm').addEventListener('submit',e=>{
  e.preventDefault();
  const d=Object.fromEntries(new FormData(e.target)),existing=state.expenses.find(item=>item.id===Number(d.id));
  if(existing?.managedBy==='commission'){showToast('Manage this automatic expense in Partners');return}
  const recipientTypes=['Supplier','Crew member','Cruise manager','Partner','Client refund','Other'];
  d.recipientType=recipientTypes.includes(d.recipientType)?d.recipientType:'Other';
  if(d.entryMode==='paid')d.status='Paid';
  if(d.status==='Paid'&&!d.paidDate){showToast('Enter the actual payment date for a paid expense.');return}
  if(d.status!=='Paid'&&!d.dueDate){showToast('Enter a payment deadline for an unpaid expense.');return}
  const normalizedPayee=d.payee.trim().toLowerCase(),contact=['Supplier','Crew member','Cruise manager'].includes(d.recipientType)?state.people.find(person=>person.type===(d.recipientType==='Supplier'?'Supplier':'Crew')&&person.name.trim().toLowerCase()===normalizedPayee):null,partner=d.recipientType==='Partner'?state.partners.find(item=>item.name.trim().toLowerCase()===normalizedPayee):null,client=d.recipientType==='Client refund'?state.clients.find(item=>item.name.trim().toLowerCase()===normalizedPayee):null;
  d.id=existing?.id||id();d.cruiseId=d.cruiseId?Number(d.cruiseId):null;d.payeePersonId=contact?.id||null;d.partnerId=partner?.id||null;d.clientId=client?.id||null;d.amount=Number(d.amount);
  if(d.status==='Paid')d.dueDate='';else d.paidDate='';
  existing?Object.assign(existing,d):state.expenses.unshift(d);
  closeModal('expenseModal');render();showToast(d.entryMode==='paid'?'Money paid recorded':`${d.category} expense saved`)
});
document.querySelector('#guestForm').addEventListener('submit',e=>{
  e.preventDefault();
  const d=Object.fromEntries(new FormData(e.target)),existing=passengerBy(Number(d.id)),isPrimary=existing?.isPrimary===true||d.isPrimary==='true';
  d.id=existing?.id||id();
  d.clientId=isPrimary?Number(existing.clientId):Number(d.clientId);
  const client=clientBy(d.clientId);
  if(!client||client.stage!=='Booked'){showToast('Choose a booked client for this passenger.');return}
  if(!existing&&passengersForClient(client.id).length>=clientPartySize(client)){showToast('The passenger list already matches the booking group size. Increase the group size in the client card first.');return}
  d.isPrimary=isPrimary;
  d.relationship=isPrimary?'Primary passenger':(d.relationship||'Passenger');
  d.status=existing?.status||'Received';
  d.deadline=existing?.deadline||'';
  d.sup=existing?.sup||'';
  d.swimming=existing?.swimming||'';
  d.dietary=existing?.dietary||'';
  d.health=existing?.health||'';
  d.terms=existing?.terms||false;
  normalizePassengerRecord(d);
  existing?Object.assign(existing,d):state.guests.push(d);
  closeModal('guestModal');
  render();
  showToast(`${d.name} saved`)
});
document.querySelector('#installmentForm').addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),existing=installmentBy(Number(d.id)),client=clientBy(Number(d.clientId)),amount=Number(d.amount);if(!client)return;d.currency=['EUR','ILS','USD'].includes(d.currency)?d.currency:'EUR';d.eurAmount=d.currency==='EUR'?amount:Number(d.eurAmount||0);if(d.eurAmount<=0){showToast('Enter the EUR equivalent used for the client balance.');return}if(existing?.paymentId&&(Number(existing.clientId)!==Number(d.clientId)||Number(existing.amount)!==amount||existing.currency!==d.currency||paymentEurValue(existing)!==d.eurAmount)){showToast('A received scheduled payment keeps its client and amount. Edit the linked payment instead.');return}const otherScheduled=state.installments.filter(item=>Number(item.clientId)===Number(client.id)&&!item.paymentId&&Number(item.id)!==Number(existing?.id)).reduce((sum,item)=>sum+paymentEurValue(item),0);if(!existing?.paymentId&&d.eurAmount+otherScheduled>balanceFor(client)){showToast(`Scheduled payments exceed the remaining balance of ${euro(balanceFor(client))}`);return}d.id=existing?.id||id();d.clientId=Number(d.clientId);d.amount=amount;d.paymentId=existing?.paymentId||null;existing?Object.assign(existing,d):state.installments.push(d);closeModal('installmentModal');render();showToast(`Scheduled payment saved for ${client.name}`)});
