document.querySelector('#commissionForm').addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),commission=state.commissions.find(item=>Number(item.id)===Number(d.id)),client=clientBy(commission?.clientId);if(!commission||!client)return;if(d.status==='Paid'&&!isPaid(client)){showToast('The client must pay in full before the partner commission is marked paid');return}d.value=Number(d.value||0);if(d.status==='Paid'&&!d.paidDate)d.paidDate=TODAY;if(d.status!=='Paid')d.paidDate='';Object.assign(commission,d,{id:commission.id,clientId:commission.clientId,partnerId:commission.partnerId,amount:calculateCommission(d.type,d.value,client)});closeModal('commissionModal');render();showToast(d.status==='Paid'?'Partner payment recorded':`Commission for ${client.name} saved`)});
